#!/usr/bin/env bash
# Verifier driver for step 08 (quiche 0.16.0).
#
# Generated by misc/quic-http3-stack-multiversion/tools/gen-step.py from the
# shared frame plus this step's group list. Edit the frame or the step part and
# regenerate; do not edit one copy in isolation. After Phase 3 opens on a step
# the generated copy becomes authoritative and the reviser edits it directly —
# `tools/carryover-check.sh` is what keeps the fifteen copies honest after that.
set -u
source /tests/helpers.sh

# --- verifier/step binding check -------------------------------------------
# Must be the first thing that runs: /etc/harbor-step-id names the image, the
# literal below names this tests/ tree, and a disagreement means the build
# context was served from another step's cache entry.
require_step 08
# --- end binding check ------------------------------------------------------

# ---------------------------------------------------------------------------
# 0. Crash path.
#
# Under `multi_step_reward_strategy = "mean"` a verifier that exits without a
# reward.json costs the whole trial the steps after it, so every exit from here
# on writes a complete scorecard and exits 0. `fail_everything` is the
# scorecard for a driver that died before it could measure anything.
#
# It reports `gate: 0` with an empty `gate_failures`, and that pairing is the
# signal: a gate of zero with no group named is the driver failing, not a
# candidate regressing. Anything that vetoes a real step names the group and
# quotes what it saw.
# ---------------------------------------------------------------------------
reported=0

fail_everything() {
    local reason="$1"
    printf '{"step":%s,"reward":0.000000,"gate":0,"score":0.000000,"gate_failures":[],"candidate_build":0,"harness_build":0,"fixture_ok":0,"budget_exhausted":0,"crate_dir":"unresolved","build_note":"%s","gate_groups":{},"scored_groups":{}}\n' \
        "${step_num:-0}" "$reason" > /logs/verifier/reward_details.json
    printf '{"reward":0.000000}\n' > /logs/verifier/reward.json
}

on_exit() {
    local status=$?
    if [ "${reported:-0}" -ne 1 ]; then
        fail_everything "the verifier driver exited with status $status before it reported: nothing was measured, so this is an unattributable verifier failure rather than a capability result"
    fi
    exit 0
}
trap on_exit EXIT

step_num=8
step_tag=0.16.0
log_dir=/tmp/quiche-verifier-08
harness=/tmp/quiche-harness-08
assets=/tests/assets
mkdir -p "$log_dir"

# ---------------------------------------------------------------------------
# 1. Fixture integrity.
#
# The verifier-owned corpus — the RFC 9001 Appendix A vectors, the frame and
# QPACK vector files, and the e2e drivers — is a prerequisite for the groups
# that consume it, never a score point of its own. A broken corpus fails those
# groups; it must not short-circuit the independent ones or erase earned
# credit.
# ---------------------------------------------------------------------------
expected_assets_sha=1053ef05efcba73dd8937ab95ae59b32cee229ef6a51b21127d62ee2546a33c0
expected_asset_files=34

actual_assets_sha=$(cd "$assets" && find . -type f -print0 | LC_ALL=C sort -z \
    | xargs -0 sha256sum | sha256sum | awk '{print $1}')
actual_asset_files=$(find "$assets" -type f | wc -l)

fixture_ok=1
[ "$actual_assets_sha" = "$expected_assets_sha" ] || fixture_ok=0
[ "$actual_asset_files" -eq "$expected_asset_files" ] || fixture_ok=0

# ---------------------------------------------------------------------------
# 2. Locating the candidate's transport crate.
#
# The library lives at the workspace root until milestone 6 and under
# `quiche/` from milestone 6 onward. Both layouts are accepted everywhere and
# the layout itself is scored by its own group at the step that introduces it,
# so a candidate that has not yet moved the tree loses that one group rather
# than every group in the step. TEST_INTERFACE.md states this probe.
# ---------------------------------------------------------------------------
crate_dir=unresolved
for cand in /app/quiche /app; do
    if [ -f "$cand/Cargo.toml" ] && grep -Eq '^[[:space:]]*name[[:space:]]*=[[:space:]]*"quiche"' "$cand/Cargo.toml"; then
        crate_dir=$cand
        break
    fi
done

workspace_root=/app
[ -f /app/Cargo.toml ] || workspace_root=$crate_dir

# ---------------------------------------------------------------------------
# 2. (continued) Which BoringSSL this tree was written against.
#
# The image pins the library this milestone's release pins, and the environment
# names it. At most steps that is the only copy and this loop does nothing.
#
# Where the QUIC callback struct changed shape across a step boundary, the
# image carries the previous release's pin as well. `SSL_QUIC_METHOD` is a
# struct of function pointers passed to `SSL_set_quic_method`: releases up to
# 0.1.0 declare four members, beginning `set_encryption_secrets`; from 0.3.0
# they declare five, beginning `set_read_secret` and `set_write_secret`. A tree
# of the older shape handed to a library of the newer one links cleanly -- the
# symbol exists and takes a pointer -- and then reads one member past the end
# of the struct, calling the wrong function for every callback. Nothing errors.
# The handshake simply never emits a ClientHello, and the step's inherited
# regression groups fail for a linkage reason wearing behaviour's clothes.
#
# So the shape is read out of the candidate's own `src/tls.rs` and the matching
# library selected. The test is deliberately two-sided -- the old name present
# AND the new names absent -- so a tree part-way through the conversion, or one
# that merely mentions the old name in a comment, keeps this release's library.
# The shape is read out of *live code*: `//` comments are stripped before the
# two greps run, so a migration note naming the old field cannot flip the pick.
# A candidate who does the work is unaffected: the environment already names
# the right one, and this loop never fires. It cannot manufacture a pass for
# the scored groups either; those ask for behaviour this milestone introduced,
# which no older library supplies.
#
# `.cargo/config.toml` in the workdir sets the same variable through cargo's
# `[env]` table, which without `force = true` yields to a variable already set
# in the environment -- so exporting here is enough, and the file stays honest
# about the default.
# ---------------------------------------------------------------------------
if [ -n "${QUICHE_BSSL_PATH:-}" ] && [ -f "$crate_dir/src/tls.rs" ] &&
    sed 's,//.*,,' "$crate_dir/src/tls.rs" | grep -q 'set_encryption_secrets' &&
    ! sed 's,//.*,,' "$crate_dir/src/tls.rs" | grep -q 'set_read_secret'; then
    for alt in /opt/bssl/*; do
        [ -d "$alt" ] || continue
        [ "$alt" = "$QUICHE_BSSL_PATH" ] && continue
        QUICHE_BSSL_PATH=$alt
        export QUICHE_BSSL_PATH
        break
    done
fi

# ---------------------------------------------------------------------------
# 2a. The time budget, and why these numbers.
#
# `task.toml` gives this step `[steps.verifier] timeout_sec = 3600`. If the
# verifier is killed by that timeout it never writes reward.json and the run is
# unattributable rather than a zero, so the work inside must provably fit
# whatever the candidate does:
#
#   verify the pinned asset corpus                               <   5 s
#   CANDIDATE_BUILD_TIMEOUT  one `cargo build` of /app, cold    <= 1000 s
#   EXAMPLES_BUILD_TIMEOUT   the best-effort examples pass      <=  240 s
#   APPS_BUILD_TIMEOUT       the best-effort app-package pass   <=  240 s
#   HARNESS_BUILD_TIMEOUT    one `cargo test --no-run` of the
#                            verifier-owned harness crate       <=  800 s
#   CASE_BUDGET_TOTAL        every gate check and every scored
#                            group together                     <= 1200 s
#   write the two JSON files                                     <   5 s
#                                                    worst case   3490 s
#
# PER_CASE_MAX is far above any real case and far below the aggregate: one
# hanging case costs its own group and at most 120 s of the shared pool, so a
# step with many hanging cases degrades group by group instead of taking the
# run down. BoringSSL and the whole dependency graph are prebuilt into the
# image, so the candidate build is the candidate's own code and nothing else.
CANDIDATE_BUILD_TIMEOUT=1000
EXAMPLES_BUILD_TIMEOUT=240
APPS_BUILD_TIMEOUT=240
HARNESS_BUILD_TIMEOUT=800
CASE_BUDGET_TOTAL=1200
PER_CASE_MAX=120

# ---------------------------------------------------------------------------
# 3. Build the candidate workspace once, before anything is scored.
#
# Recorded separately from the groups: every group runs against this build, so
# one compile error would otherwise be reported as N unrelated capability gaps.
# ---------------------------------------------------------------------------
candidate_build=0
if [ "$crate_dir" != unresolved ]; then
    # Default targets only -- libraries and binaries. Deliberately not
    # `--all-targets`: that would also compile the candidate's own test and
    # bench targets, so a broken test of theirs would fail the build and be
    # reported as every capability missing at once. Their tests are not what
    # this verifier measures.
    (cd "$workspace_root" && timeout "$CANDIDATE_BUILD_TIMEOUT" \
        cargo build --offline -j 4) \
        >"$log_dir/candidate-build.log" 2>&1 && candidate_build=1
    # The client and server lived under examples/ before they became their own
    # package. Best-effort and never fatal: at releases where they are bins the
    # build above already produced them, and at releases where there are no
    # examples this is a no-op.
    if [ "$candidate_build" -eq 1 ]; then
        (cd "$workspace_root" && timeout "$EXAMPLES_BUILD_TIMEOUT" \
            cargo build --offline --examples -j 4) \
            >"$log_dir/candidate-examples.log" 2>&1 || true
    fi
    # Later they moved out of examples/ and into a package of their own --
    # `tools/apps` first, then `apps`. Where that package is a workspace member
    # the build above already covered it; where it exists but the root manifest
    # has no [workspace] section, cargo never descends into it, so the tree
    # ships the client and server sources and produces neither binary. Building
    # the package where it sits covers that window, and builds more of the
    # candidate rather than asking less of it.
    #
    # Best-effort, like the examples pass, and bounded as one pass rather than
    # one per path: at a release whose lockfile predates this package's own
    # dependencies it cannot resolve offline at all, which is a property of the
    # pinned corpus and not a candidate defect. Building a non-member package
    # makes cargo write a lockfile beside its manifest; no group reads one.
    if [ "$candidate_build" -eq 1 ]; then
        apps_deadline=$(( $(date +%s) + APPS_BUILD_TIMEOUT ))
        for app in tools/apps apps; do
            [ -f "$workspace_root/$app/Cargo.toml" ] || continue
            left=$(( apps_deadline - $(date +%s) ))
            [ "$left" -gt 0 ] || break
            (cd "$workspace_root/$app" && timeout "$left" \
                cargo build --offline -j 4) \
                >"$log_dir/candidate-app-$(printf '%s' "$app" | tr / -).log" \
                2>&1 || true
        done
    fi
fi

# The client and server binaries are the process boundary most groups use.
# The harness resolves them itself, by name, from the CANDIDATE_* variables
# below -- the names are the step's own interface section's, and the harness
# applies them name-major over the directories it searches. The driver does
# not pre-resolve a binary and does not prefer any spelling of its own: a
# second resolution rule written here could only ever disagree with that one.
target_dir=${CARGO_TARGET_DIR:-$workspace_root/target}

export QUICHE_CRATE_DIR="$crate_dir"
export QUICHE_WORKSPACE="$workspace_root"
export QUICHE_ASSETS="$assets"
export QUICHE_LOGDIR="$log_dir"

# What `verifier::testkit` reads. The harness has to find the candidate's
# binaries, and in this image they are not under /app/target: CARGO_TARGET_DIR
# is set image-wide so the prewarmed dependency graph is reused, which moves
# every artefact to /opt/cargo-target. Telling the harness where the tree and
# the artefacts actually are keeps that an image detail instead of something
# each of the fifteen steps' test files has to know.
export CANDIDATE_ROOT="$workspace_root"
export CANDIDATE_TARGET_DIR="$target_dir"
# Scratch directories are deliberately never cleaned up: when a case fails, the
# document root, the captured stdout and the server log it left behind are the
# evidence. Rooting them in the log directory keeps them beside the case log.
export VERIFIER_SCRATCH="$log_dir/scratch"
mkdir -p "$VERIFIER_SCRATCH"

# ---------------------------------------------------------------------------
# 4. The throw-away harness crate.
#
# It lives outside /app so that a candidate cannot make its own acceptance pass
# by editing the cases, and so that nothing the harness needs is ever added to
# the candidate's manifest. It declares exactly one dependency — a path
# dependency on the candidate's own transport crate — so a harness build
# failure is always about the candidate's public surface and never about a
# registry.
# ---------------------------------------------------------------------------
# Does the candidate's manifest declare a Cargo feature by this name?
#
# Either an explicit entry under [features], or an optional dependency of the
# same name, which Cargo turns into a feature implicitly.
# Does the candidate's manifest declare `$2` as a feature?
#
# Three spellings are legal Cargo for "this crate can be built with a `qlog`
# feature", and all three have to be recognised or a correct manifest is read
# as not declaring it, the feature is dropped from the harness's own edge, and
# every `cap` group fails to link for a reason that is not the candidate's:
#
#   [features]
#   qlog = []
#
#   [dependencies]
#   qlog = { version = "..", optional = true }
#
#   [dependencies.qlog]
#   optional = true
#
# The third puts the name in the section header and never in field 1, which is
# why the spelling is tracked as well as the key.
declares_feature() {
    awk -v want="$2" '
        /^[[:space:]]*\[/ {
            sec = $1
            gsub(/^\[|\]$/, "", sec)
            section = sec
            dep_table = (sec == "dependencies." want || sec == "dev-dependencies." want \
                         || sec == "build-dependencies." want)
            next
        }
        $1 == want && $2 == "=" && section == "features" { found = 1 }
        $1 == want && $2 == "=" && section ~ /dependencies$/ \
            && $0 ~ /optional[ \t]*=[ \t]*true/ { found = 1 }
        dep_table && $1 == "optional" && $2 == "=" && $3 == "true" { found = 1 }
        END { exit found ? 0 : 1 }
    ' "$1"
}

prepare_harness() {
    rm -rf -- "$harness"
    mkdir -p "$(dirname "$harness")"
    # The whole tree, not a hand-listed subset: the harness is a two-member
    # workspace (the verifier crate and `support/`, the independent QUIC
    # implementation) and it carries its own `assets/` — the TLS keypair and
    # the RFC vectors the cases load through `testkit::asset`. Copying file
    # patterns instead would silently drop whichever of those a future step
    # starts using, and the resulting build failure would be charged to the
    # candidate.
    cp -a -- "$assets/harness" "$harness"
    # The only edit: the candidate's crate path, which is not known until the
    # probe above has run. Resolved here rather than in the checked-in manifest
    # so the manifest stays identical in all fifteen steps.
    sed -i "s#@@CRATE_DIR@@#$crate_dir#g" "$harness/Cargo.toml"
    # Optional feature requests, resolved against the candidate's own manifest.
    #
    # Cargo validates every feature reference while it resolves the graph,
    # before it compiles anything, so asking a milestone for a feature it does
    # not declare fails the whole harness build -- including the gate targets,
    # which never touch the feature. Names marked `# optional-feature:` in the
    # harness manifest are therefore kept only when the candidate declares
    # them. The scored case that needs one then fails to compile by itself,
    # which is the right answer for a candidate that has not built it.
    for feat in $(sed -n 's/^#[[:space:]]*optional-feature:[[:space:]]*//p' \
        "$harness/Cargo.toml"); do
        if declares_feature "$crate_dir/Cargo.toml" "$feat"; then
            printf 'kept optional feature %s\n' "$feat" \
                >>"$log_dir/harness-features.log"
        else
            sed -i "s/\"$feat\"[[:space:]]*,[[:space:]]*//; s/,[[:space:]]*\"$feat\"//; s/\"$feat\"//" \
                "$harness/Cargo.toml"
            printf 'dropped optional feature %s: the candidate does not declare it\n' \
                "$feat" >>"$log_dir/harness-features.log"
        fi
    done
    # No lockfile, on purpose. One authored against the reference tree would
    # pin the candidate's own dependency versions, turning a legitimate
    # difference in their manifest into a harness build failure that reads as
    # their fault. The registry cache is prewarmed, so resolving offline here
    # costs nothing.
    rm -f -- "$harness/Cargo.lock"
}

harness_build=0
if [ "$candidate_build" -eq 1 ]; then
    prepare_harness
    (cd "$harness" && timeout "$HARNESS_BUILD_TIMEOUT" \
        cargo test --offline --no-run -j 4) \
        >"$log_dir/harness-build.log" 2>&1 && harness_build=1
fi

# The case pool starts here, so a slow build cannot eat it.
case_deadline=$(( $(date +%s) + CASE_BUDGET_TOTAL ))
budget_exhausted=0

# remaining_budget -> seconds left in the shared pool, or 0
remaining_budget() {
    local r=$(( case_deadline - $(date +%s) ))
    [ "$r" -lt 0 ] && r=0
    printf '%s\n' "$r"
}

# run_case <log-name> <test-target> <test-fn>
#
# Each case is bounded by the smaller of PER_CASE_MAX and what is left of
# CASE_BUDGET_TOTAL, so the cases can never overrun that total however many of
# them hang. A killed case exits non-zero and scores that one group 0, which is
# the same outcome as any other failure; once the pool is spent the remaining
# groups are failed without running and the reason is recorded, which is still a
# zero rather than a lost run.
run_case() {
    local name="$1" target="$2" fn="$3" remaining limit status
    remaining=$(remaining_budget)
    if [ "$remaining" -le 5 ]; then
        budget_exhausted=1
        printf 'the aggregate case budget of %s s was exhausted before this case ran\n' \
            "$CASE_BUDGET_TOTAL" >"$log_dir/$name.log"
        return 1
    fi
    if [ ! -d "$harness" ]; then
        # The harness crate is assembled only after a candidate transport crate
        # has been located. When it was not, every case here would fail on `cd`
        # with a shell error in its log, which reads as a broken driver rather
        # than as a result. The group does fail -- but for a definite reason,
        # and the reason belongs on the group that fired it.
        {
            printf 'the harness crate was never assembled, so this case could not run.\n'
            printf 'assembly is skipped when no candidate transport crate was located\n'
            printf '(crate_dir=%s): there was nothing for the harness to link against.\n' "$crate_dir"
            printf 'This group fails for that reason, not for anything it asserts.\n'
        } >"$log_dir/$name.log"
        return 1
    fi
    limit=$PER_CASE_MAX
    [ "$remaining" -lt "$limit" ] && limit=$remaining
    (cd "$harness" && timeout "$limit" \
        cargo test --offline --test "$target" "$fn" -- --exact --nocapture) \
        >"$log_dir/$name.log" 2>&1
    status=$?
    [ "$status" -eq 0 ] || return "$status"
    # Every invocation asserts an exact executed count: a name filter that
    # matches nothing still exits 0, and would otherwise be scored as a pass.
    grep -q 'test result: ok\. 1 passed; 0 failed; 0 ignored' "$log_dir/$name.log"
}

# ---------------------------------------------------------------------------
# 5. The gate.
#
# Proof of life plus inherited regression: that the candidate builds, that its
# two binaries still complete a handshake and a transfer over real UDP, and
# that one deterministic end-to-end path per earlier milestone still works.
#
# Gate groups earn nothing. They only veto: if any one of them fails the step
# is worth zero however much of this step's own capability landed. That is
# deliberate. A candidate that implements this release by breaking the last one
# has not advanced the ladder, and an additive score would pay it for the parts
# that still happen to work.
#
# The corollary governs what is allowed in here. A gate case that can fail for
# a reason other than the candidate's code -- a wall clock, a host's CPU count,
# an unordered iteration read as ordered -- is not weak coverage, it is a step
# that randomly scores zero for everyone including the reference. Every case
# below is deterministic, and the ones that were not were deleted rather than
# demoted; NOTES.md lists them and why.
#
# Behaviour this step deliberately changes is likewise not in here. A migration
# left in the gate is a step whose own reference implementation fails it.
# ---------------------------------------------------------------------------
gate_ok=1
gate_log=$log_dir/gate.txt
: > "$gate_log"

gate_check() {
    local name="$1"; shift
    if "$@"; then
        printf 'PASS %s\n' "$name" >> "$gate_log"
    else
        printf 'FAIL %s\n' "$name" >> "$gate_log"
        gate_ok=0
    fi
}

candidate_builds() { [ "$candidate_build" -eq 1 ]; }

# Every other gate group is a case or a driver and leaves `$log_dir/<name>.log`
# behind, which is where the scorer reads the reason a veto fired. This one is
# a flag set back in section 3, so give it the log the flag came from.
if [ -f "$log_dir/candidate-build.log" ]; then
    cp -f "$log_dir/candidate-build.log" "$log_dir/candidate-workspace-builds.log"
else
    # Section 3 runs cargo only when a quiche crate was located. When it was
    # not, no candidate-build.log exists, and copying it silently left this
    # group with no log at all -- which the scorer reports as "the case did not
    # run". That reads like a harness that failed to fire, when in fact the
    # group failed for a definite reason. A veto must carry its reason on the
    # group that fired it, so write it here rather than leave the scorer to
    # guess. The step-level build_note says the same thing; this puts it where
    # a reader looks first.
    {
        printf 'no cargo build was attempted: crate_dir=%s\n' "$crate_dir"
        printf 'no Cargo.toml declaring the package name `quiche` was found at\n'
        printf '/app or /app/quiche, so there was no transport crate to build.\n'
        printf 'This group fails by definition: proof-of-life cannot pass when\n'
        printf 'the candidate shipped no library to prove alive.\n'
    } > "$log_dir/candidate-workspace-builds.log"
fi
gate_check candidate-workspace-builds candidate_builds
# T1: Inherited from step 01: the candidate's `client` fetches a 512 KiB pseudorandom file from the candidate's `server` over loopback and the bytes match exactly. The path API is additive, so ordinary single-path transfers must be completely unaffected -- and this is the group that catches the usual casualty of a multi-path refactor, which is that every send now goes through path lookup and the one-path case was the last thing anyone retested. The client is given `--http-version HTTP/0.9` rather than left to negotiate. Step 01 scored this observation over the byte-stream protocol, and an inherited group has to re-run the observation it inherited; routing it through HTTP/3 would quietly make it a different group.
gate_check reg-01-stream-transfer run_case reg-01-stream-transfer reg reg_01_stream_transfer
# T3: Inherited from step 04: DATAGRAM frames still round-trip, with both peers enabling them via `enable_dgram(true, 10, 10)` and a 256-byte payload echoed back byte-for-byte. A datagram is bound to a path and is not retransmitted, so of everything carried forward this is what the multi-path refactor is most likely to break and least likely to break loudly.
gate_check reg-04-datagram-roundtrip run_case reg-04-datagram-roundtrip reg reg_04_datagram_roundtrip
# T3: Inherited from step 07: the HTTP/3 PRIORITY_UPDATE frame and its event, re-run with the same five stages and the same claims as step 07's own group -- one frame raises one event, a second update for an unread element raises none but replaces the stored value, taking it hands back the latest value once, the event then rearms, and a different prioritised element is stored beside the first rather than over it. This group also covers the ALPN change from a second angle: an HTTP/3 layer whose application protocols no longer negotiate never opens a control stream at all, so a careless edit to `set_application_protos` fails here, long before it reaches priorities, as well as in `cap-alpn-list-shape`.
gate_check reg-07-priority-update run_case reg-07-priority-update reg reg_07_priority_update
# T1: The candidate's `server` starts, the candidate's `client` completes a handshake against it over UDP loopback and retrieves a small file, and both exit zero. No migration, no flags: if this fails, every other observation at this step is noise.
gate_check gate-endtoend run_case gate-endtoend gate gate_endtoend

# ---------------------------------------------------------------------------
# 6. The scored groups.
#
# This step's new capability, plus peripheral breadth. Each group is one
# coherent behaviour and is invoked separately, so a failure localises, and
# every group runs even after another has failed: a partial implementation
# keeps exactly the credit it earned.
#
# Weights live in `/tests/groups.json` and sum to one across the groups here,
# so this step's score is in [0, 1] and is the weighted fraction of its own new
# behaviour that works. Nothing in this section knows a weight -- it records
# PASS or FAIL per group and the scorer prices it -- so a revision that edits a
# group here cannot silently desync the driver from the manifest.
# ---------------------------------------------------------------------------
group_log=$log_dir/groups.txt
: > "$group_log"

score_if() {
    local name="$1"; shift
    if "$@"; then
        printf 'PASS %s\n' "$name" >> "$group_log"
    else
        printf 'FAIL %s\n' "$name" >> "$group_log"
    fi
}

# T1: The candidate's own `client`, run with `--perform-migration` against the candidate's `server`, completes a transfer while moving to a second local address. The grader starts the server, runs the client with the flag and a 512 KiB pseudorandom file to fetch, and requires the retrieved bytes to be byte-identical and the client to exit zero. The second half of the group is what stops a client that accepts the flag and ignores it. While the client runs, the grader polls that process's own open file descriptors -- `/proc/<pid>/fd` resolved against `/proc/net/udp` and `/proc/net/udp6` -- and records every local port it ever holds a UDP socket bound to. Migrating to a second local address means binding a second socket, so the group requires **two distinct bound local ports** over the life of the process. This is an observation of the candidate's own process, needs no privileges and no packet capture, and is independent of how any implementation words its logs: the reference client's migration evidence is `info!` text, and grading on that text would score upstream's log wording rather than a capability. The grader leaves `--source-port` at its default of 0 so that both sockets take ephemeral ports; pinning it would make the second bind collide. A candidate whose client rejects `--perform-migration` exits non-zero and scores nothing here, which is also why this group is empty at step 07, where the flag does not exist. The limit of the observation is stated rather than hidden: two bound sockets is evidence of a second local address, not proof that a datagram ever left the second one, and no privilege-free surface at this release proves the latter -- `/proc/net/udp` has no per-socket byte counter and qlog gained no path events until after this milestone. An implementation that binds a decoy socket and never migrates would pass this group. The transport-level groups beside it are where migration itself is actually decided; this group's job is to show the capability reaching the candidate's own application.
score_if cap-probe-and-migrate run_case cap-probe-and-migrate cap cap_probe_and_migrate
# T3: A `pair::Pair` handshakes with `set_active_connection_id_limit(2)`, both peers issue a connection ID with `new_source_cid` and exchange packets until each reports `available_dcids() == 1`, and only then does the client call `probe_path` for a second local address. The group asserts that ordering is load-bearing: called before that exchange, `probe_path` returns `Err(Error::OutOfIdentifiers)`, and the group checks that first. Then it asserts the asymmetry of the event queues, which is the part an implementation is most likely to get wrong by making them symmetric. The **client** sees exactly one event, `Validated(client_local_2, server)`, and then `None` -- it never sees `New`, because the client is the side that initiates paths. The **server** sees two, in order: `New(server, client_local_2)` and then `Validated(server, client_local_2)`, and then `None`. Both of the server's events arrive without the application probing back; a server that only reports `New` and waits to be told what to do fails here. The addresses are asserted, not just the variants, so filling the tuple in the other order fails. And `None` is asserted after each queue drains, so an implementation that re-reports its most recent event indefinitely fails even though every individual event it reports is correct.
score_if cap-path-events run_case cap-path-events cap cap_path_events
# T3: One `pair::Pair`, one datagram in each direction, four assertions -- that `SendInfo.from` is the sender's local address, `SendInfo.to` is the peer's address, `RecvInfo.from` is the sender's address, and `RecvInfo.to` is the receiver's local address. Both structs have both fields at step 07's tree too, so this group is not about presence. It is about `to` meaning the remote endpoint on the way out and the local endpoint on the way in. A stack that populates the two structs symmetrically -- the reading that feels natural, and the one a single shared helper produces -- gets two of the four assertions wrong.
score_if cap-sendinfo-from run_case cap-sendinfo-from cap cap_sendinfo_from
# T3: `Config::set_cc_algorithm_name("bbr")` returns `Ok`, a `pair::Pair` built on that config completes a handshake, and a 256 KiB transfer through it arrives byte-identical with a congestion window that grew above its initial value. The group does not check BBR's state machine or its pacing decisions -- that would score an implementation rather than a capability, and reasonable BBRs differ. It checks that the name resolves, that the connection works under it, and that the controller opens the window under sustained load. For contrast it also asserts `set_cc_algorithm_name("cubic")` still returns `Ok` and that an unknown name returns `Err(Error::CongestionControl)` specifically, so a stack that accepts every string indiscriminately, or that silently falls back to the default, fails. Alongside BBR itself, the group checks two things that hold regardless of which algorithm is running. First, the discriminant layout the interface section above documents: `CongestionControlAlgorithm::Reno as u8`, `::CUBIC as u8` and `::BBR as u8` are asserted equal to `(0, 1, 2)` in one tuple, catching a BBR that compiles and works but was inserted at 1 or 2 in a way that renumbers CUBIC. Second, `Connection::stats()` is read back through an exhaustive twenty-two-field destructure of `quiche::Stats` -- naming every field once, with no `..` rest pattern, so a stack that has removed one of the four fields `PathStats` took over at this milestone (`cwnd`, `rtt`, `pmtu`, `delivery_rate`) fails to compile here rather than passing with the field silently still present. `sent_bytes`, `paths_count`, the four packet/byte counters and all thirteen `peer_*` transport-parameter fields are then asserted against concrete values traced to `pair::tune()` (or, for the two parameters `tune()` never touches, RFC 9000 Section 18.2's own defaults) -- driven non-zero by the transfer above rather than left at their post-handshake defaults, so their presence is a fact about behaviour rather than a fact about initialization.
score_if cap-bbr run_case cap-bbr cap cap_bbr
# T3: `Connection::migrate(local, peer)` itself, called by name -- distinct from `cap-probe-and-migrate`, which drives the reference client binary and never calls the method directly, and from `cap-path-events`, which probes a second path but never migrates onto it. A server calling `migrate()` is refused with `Error::InvalidState` unconditionally, before any connection ID or path state is even considered. A client that has probed and validated a second path (the same `exchange_cids` / `probe_path` / settle sequence `cap-path-events` uses) calls `migrate()` onto it and gets back `Ok(1)`, the destination connection ID sequence number of the path just made active -- the same return contract `probe_path` documents. A second call naming the same, already-active path also returns `Ok(1)`: migrating is idempotent, not a one-shot trigger that errors the second time. Real transfers cross both before and after the call, so the packet and byte counters below are driven by traffic rather than left at their post-handshake defaults. Before migrating, the original path reads `active: true` and the validated second path reads `active: false` -- probing validates a path, it does not make it active. After migrating, that is exactly reversed, and the original path is still present in `path_stats()` with its own counters intact: migrating away from a path does not remove it. The group then reads every field `PathStats` has on the now-active path through an exhaustive sixteen-field destructure -- naming each field once, `..` never used, so a seventeenth field or a renamed one fails to compile. Nine of the sixteen fields are not read by any other group in this step's harness: `recv`, `sent_bytes`, `recv_bytes`, `lost_bytes`, `stream_retrans_bytes`, `rtt`, `cwnd`, `pmtu` and `delivery_rate`. All but `delivery_rate` are asserted -- `rtt` and the four counters positive, `cwnd` and `pmtu` positive, nothing lost or retransmitted on a lossless in-memory path; `delivery_rate` is read to complete the shape and left otherwise unchecked, a rate estimate with no specified formula. `validation_state` is asserted equal to the original path's own `validation_state` rather than to a literal: `PathState`, the type of the field, is not re-exported at the crate root at this milestone, so an external test cannot name one of its variants at all, only compare same-typed values for equality.
score_if cap-migrate run_case cap-migrate cap cap_migrate
# T3: The two `PathEvent` variants no other group in this step's harness ever provokes: every other path-event group only ever sees a probe succeed. `FailedValidation`: a client probes a second path and its PATH_CHALLENGE is emitted and then simply never delivered, three times in a row, with the client's own `Connection::timeout()` read fresh and slept out between attempts rather than a fixed sleep assumed. Three consecutive lost probes is what this milestone's reference behaviour turns into a failure rather than a fourth retransmission, and `path_event_next()` is asserted to yield exactly `FailedValidation(local, peer)` once they have. `Closed`: a server evicts an unused path to make room for a new one once `active_connection_id_limit` -- 2, the value `pair::tune()` sets on both configs in every group in this file -- is reached. With no socket to rebind, a passively-observed path is built the way a NAT rebinding a client's port looks to a server: two distinct real client packets (never one packet replayed, which the connection's own packet-number space would reject as a duplicate) are each delivered to the server carrying the same source connection ID but a different, never-before-seen source address. The first is admitted as a new, unused, unvalidated path beside the real one; the second pushes the path count over the limit, and the first spoofed path -- still unused, nobody having probed it or made it active -- is the one evicted. The event order across both deliveries is asserted exactly: `ReusedSourceConnectionId`, then (on the second delivery only) `Closed` for the evicted path, then `New` for the one just admitted -- and the connection is asserted still open throughout. An unused path that carries a non-probing frame is not stable enough to evict: this milestone follows a peer's migration the moment a packet on a different path is the highest-numbered non-probing packet the connection has seen, and an active path is never `unused`. Each spoofed packet is therefore captured with `Connection::send()` but held back, and only delivered under its spoofed address after a later-numbered packet has already crossed on the real path, so it is no longer the connection's newest non-probing packet. No spare destination connection ID is ever issued to the connection either (`exchange_cids()` is deliberately skipped), so the path cannot silently stop being `unused` by being handed one.
score_if cap-path-failure run_case cap-path-failure cap cap_path_failure
# T3: After a handshake with `set_active_connection_id_limit(2)`, the client calls `new_source_cid` with a fresh connection ID, a stateless-reset token and `retire_if_needed = false`. The call returns **`Ok(1)`** -- the first issued connection ID is sequence 1, because sequence 0 came from the handshake. The pair is then driven and the server's `available_dcids()` must have risen, which is the observable consequence of the NEW_CONNECTION_ID frame arriving. Issuing past the peer's limit with `retire_if_needed = false` must return `Err(Error::IdLimit)` rather than succeeding silently or panicking, and `source_cids_left()` must reach 0 at that boundary rather than going negative or saturating.
score_if cap-new-source-cid run_case cap-new-source-cid cap cap_new_source_cid
# T3: With a validated second path in hand, `send_on_path(buf, Some(local), Some(peer))` names a path the connection knows and the returned `SendInfo` describes exactly that path -- `from` equal to the `local` asked for, `to` equal to the `peer`. The teeth are the negative case: `send_on_path` with a four-tuple the connection has never seen returns `Err(Error::InvalidState)`. It does not fall back to the active path, which is the failure mode that leaves a migration bug invisible until it is a packet on the wrong network. The group asserts the specific variant, not merely that the call failed. It does not assert that `send_on_path(buf, None, None)` matches `send(buf)`: in a correct implementation `send` is defined as that call, so the equivalence is true by construction and proves nothing about the candidate. Two path-inspection methods are exercised alongside the sends. `paths_iter` is asserted twice, positively and negatively: from the second local address it must report the server reachable as soon as that path has been probed, and from a local address the connection holds no path on it must report nothing. `path_stats()` is read for the per-path numbers, and is the accessor used here rather than `paths_iter` precisely because it reports every path the connection holds rather than only the reachable ones.
score_if cap-send-on-path run_case cap-send-on-path cap cap_send_on_path
# T3: `quiche::h3::APPLICATION_PROTOCOL` iterates as four elements whose lengths are 2, 5, 5 and 5 and whose contents are `h3`, `h3-29`, `h3-28`, `h3-27` -- a list of names, with no length byte inside any element. At step 07 the same constant is one 21-byte buffer with the lengths embedded, so this assertion separates the two milestones without reading anyone's source. `Config::set_application_protos` accepts that list and a `H3Pair` built through it negotiates `h3`. Separately, `set_application_protos_wire_format` accepts the old packed buffer `b"\x02h3\x05h3-29\x05h3-28\x05h3-27"` and a `H3Pair` built through *it* negotiates `h3` as well -- which is what makes the change a rename rather than a deletion, and what a candidate who simply deleted the old code path fails.
score_if cap-alpn-list-shape run_case cap-alpn-list-shape cap cap_alpn_list_shape
# T3: Both peers issue a spare connection ID and exchange packets, so the client holds two destination connection IDs: the handshake's sequence 0 and the spare sequence 1. It then retires the handshake's. The call returns `Ok(())`, the pair is driven, and the peer observes the retirement through `retired_scid_next()` returning that exact connection ID and then `None`. Stream data still flows afterwards: retiring a connection ID is a rotation, not a teardown. Two refusals are asserted by variant, because they are different conditions and an implementation that conflates them is wrong about one of them. Retiring a sequence number the connection does not have is `Err(Error::InvalidState)` -- there is nothing to retire. Retiring the last remaining destination connection ID is `Err(Error::OutOfIdentifiers)` -- there is something to retire, and retiring it would leave the connection unable to address its peer at all. The order the three calls are made in is part of the observation. The unknown-sequence case is exercised first, while a spare still exists, because the emptiness condition is checked ahead of the lookup and would otherwise hide it; the last-one-standing case is exercised at the end, once the spare has been consumed. A group that ran them the other way round would be asserting a single error twice.
score_if cap-retire-destination-cid run_case cap-retire-destination-cid cap cap_retire_destination_cid

# ---------------------------------------------------------------------------
# 7. Report.
#
#     reward = gate x score
#
# `score.py` does the arithmetic against the manifest, because the two checks
# that matter are both about groups going missing -- a declared group with no
# recorded result, or a recorded result for a group nobody priced -- and both
# are easier to get right over parsed JSON than over shell word splitting. It
# prints the reward and writes reward_details.json, naming the gate group that
# vetoed the step and quoting what it saw.
#
# If it cannot run at all, that is a verifier defect and not a capability
# result, and the crash path in section 0 says so in those words.
# ---------------------------------------------------------------------------
score_input=$(printf '{"step_num":%d,"tag":"%s","log_dir":"%s","manifest":"/tests/groups.json","crate_dir":"%s","candidate_build":%s,"harness_build":%s,"fixture_ok":%s,"budget_exhausted":%s}\n' \
    "$step_num" "$step_tag" "$log_dir" "$crate_dir" \
    "$([ "$candidate_build" -eq 1 ] && echo true || echo false)" \
    "$([ "$harness_build" -eq 1 ] && echo true || echo false)" \
    "$([ "$fixture_ok" -eq 1 ] && echo true || echo false)" \
    "$([ "$budget_exhausted" -eq 1 ] && echo true || echo false)")

reward=$(printf '%s' "$score_input" | python3 /tests/score.py 2>"$log_dir/score.err")
score_status=$?

case "$reward" in
    0|0.*|1|1.0*) ;;
    *) reward='' ;;
esac

if [ "$score_status" -ne 0 ] || [ -z "$reward" ]; then
    fail_everything "the verifier could not score this step: score.py exited $score_status saying '$(tr -d '\n"\\' < "$log_dir/score.err" | tail -c 300)'. Nothing was measured, so this is an unattributable verifier failure rather than a capability result"
    reported=1
    exit 0
fi

reported=1
report "$reward"
exit 0
